import { Metadata } from "next";
import fs from "node:fs";
import path from "node:path";

const siteUrl =
  process.env.NEXT_PUBLIC_SITE_URL || "https://inject3r.github.io";
const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "/ip-address-database";

export async function generateStaticParams() {
  const countryIndexPath = path.join(
    process.cwd(),
    "public",
    "data",
    "country.json",
  );

  if (!fs.existsSync(countryIndexPath)) {
    return [];
  }

  const countryIndex = JSON.parse(
    fs.readFileSync(countryIndexPath, "utf8"),
  ) as { countries?: Array<{ code?: string }> };

  return (
    countryIndex.countries?.map((country) => ({
      countryCode: String(country.code || "").toLowerCase(),
    })) || []
  );
}

interface CountryLayoutProps {
  children: React.ReactNode;
  params: Promise<{ countryCode: string }> | { countryCode: string };
}

export async function generateMetadata({
  params,
}: CountryLayoutProps): Promise<Metadata> {
  const resolvedParams = await Promise.resolve(params);
  const countryCode = resolvedParams.countryCode.toUpperCase();
  const countryPath = `${basePath}/country/${resolvedParams.countryCode.toLowerCase()}`;

  return {
    title: `${countryCode} IP Database`,
    description: `Browse IPv4 and IPv6 network ranges, CIDR blocks, and IP allocation data for ${countryCode}. Discover country-level network coverage and routing information.`,
    keywords: [
      `${countryCode} IP database`,
      `${countryCode} network ranges`,
      `IPv4 ${countryCode}`,
      `IPv6 ${countryCode}`,
      `country ASN lookup`,
      `IP geolocation ${countryCode}`,
    ],
    alternates: {
      canonical: `${siteUrl}${countryPath}/`,
    },
    openGraph: {
      title: `${countryCode} IP Database`,
      description: `Explore network ranges and IP allocation data for ${countryCode}.`,
      type: "website",
      url: `${siteUrl}${countryPath}/`,
      siteName: "IP Address Database",
      locale: "en_US",
    },
    twitter: {
      card: "summary_large_image",
      title: `${countryCode} IP Database`,
      description: `IPv4 and IPv6 network data for ${countryCode}.`,
      creator: "@inject3r",
    },
  };
}

export default function CountryLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return <>{children}</>;
}
